int x25_negotiate_facilities(struct sk_buff *skb, struct sock *sk,
                             struct x25_facilities *new,
                             struct x25_dte_facilities *dte)
{
    struct x25_facilities facilities;
    u8 *ptr = skb->data;
    int len = skb->len;
    int i;

    /* Initialize the facilities structures */
    memset(&facilities, 0, sizeof(facilities));
    memset(new, 0, sizeof(*new));
    memset(dte, 0, sizeof(*dte));

    /* Parse the incoming facilities from the socket buffer */
    for (i = 0; i < len; i += 2) {
        u8 type = ptr[i];
        u8 value = ptr[i + 1];

        switch (type) {
            case X25_FAC_THROUGHPUT:
                facilities.throughput = value;
                break;
            case X25_FAC_PACKET_SIZE:
                facilities.packet_size = value;
                break;
            case X25_FAC_WINDOW_SIZE:
                facilities.window_size = value;
                break;
            case X25_FAC_REVERSE_CHARGE:
                facilities.reverse_charge = value;
                break;
            default:
                break;
        }
    }

    /* Check for reverse charging requests */
    if (facilities.reverse_charge) {
        if (sk->sk_type == SOCK_SEQPACKET)
            new->reverse_charge = facilities.reverse_charge;
        else
            return -EINVAL;
    }

    /* Negotiate throughput */
    if (facilities.throughput > X25_FAC_THROUGHPUT_DEFAULT)
        new->throughput = min(facilities.throughput, X25_FAC_THROUGHPUT_DEFAULT);
    else
        new->throughput = facilities.throughput;

    /* Negotiate packet size */
    if (facilities.packet_size > X25_FAC_PACKET_SIZE_DEFAULT)
        new->packet_size = min(facilities.packet_size, X25_FAC_PACKET_SIZE_DEFAULT);
    else
        new->packet_size = facilities.packet_size;

    /* Negotiate window size */
    if (facilities.window_size > X25_FAC_WINDOW_SIZE_DEFAULT)
        new->window_size = min(facilities.window_size, X25_FAC_WINDOW_SIZE_DEFAULT);
    else
        new->window_size = facilities.window_size;

    /* Copy DTE facilities */
    dte->throughput = new->throughput;
    dte->packet_size = new->packet_size;
    dte->window_size = new->window_size;

    /* Log significant negotiation decisions */
    if (new->reverse_charge)
        printk(KERN_DEBUG "X.25: Reverse charge facility enabled.\n");

    return len;
}

int x25_negotiate_facilities(struct sk_buff *skb, struct sock *sk,
                             struct x25_facilities *new,
                             struct x25_dte_facilities *dte)
{
    struct x25_facilities dce;
    struct x25_facilities *dte_fac;
    unsigned char *ptr;
    int len;

    ptr = skb->data;

    /* Initialize facilities structures */
    memset(&dce, 0, sizeof(dce));
    dce.throughput = X25_DEFAULT_THROUGHPUT;
    dce.packet_size = X25_DEFAULT_PACKET_SIZE;
    dce.window_size = X25_DEFAULT_WINDOW_SIZE;
    dce.reverse_charging = 0;
    dce.forward_charging = 0;
    dce.call_back = 0;
    dce.priority = 0;
    dce.etr = 0;
    dce.etx = 0;
    dce.ack_timeout = 0;
    dce.window_timeout = 0;
    dce.etx_timeout = 0;

    /* Parse incoming facilities */
    len = 0;
    while (len < skb->len) {
        unsigned char type = *ptr++;
        unsigned char length = *ptr++;

        len += 2;
        if (length == 0)
            break;

        switch (type) {
        case X25_FAC_THROUGHPUT:
            if (length != 1)
                return -EINVAL;
            dce.throughput = *ptr++;
            len += 1;
            break;
        case X25_FAC_PACKET_SIZE:
            if (length != 2)
                return -EINVAL;
            dce.packet_size = get_unaligned((unsigned short *)ptr);
            ptr += 2;
            len += 2;
            break;
        case X25_FAC_WINDOW_SIZE:
            if (length != 1)
                return -EINVAL;
            dce.window_size = *ptr++;
            len += 1;
            break;
        case X25_FAC_REVERSE_CHARGING:
            if (length != 1)
                return -EINVAL;
            dce.reverse_charging = *ptr++;
            len += 1;
            break;
        case X25_FAC_FORWARD_CHARGING:
            if (length != 1)
                return -EINVAL;
            dce.forward_charging = *ptr++;
            len += 1;
            break;
        case X25_FAC_CALL_BACK:
            if (length != 1)
                return -EINVAL;
            dce.call_back = *ptr++;
            len += 1;
            break;
        case X25_FAC_PRIORITY:
            if (length != 1)
                return -EINVAL;
            dce.priority = *ptr++;
            len += 1;
            break;
        case X25_FAC_ETR:
            if (length != 2)
                return -EINVAL;
            dce.etr = get_unaligned((unsigned short *)ptr);
            ptr += 2;
            len += 2;
            break;
        case X25_FAC_ETX:
            if (length != 2)
                return -EINVAL;
            dce.etx = get_unaligned((unsigned short *)ptr);
            ptr += 2;
            len += 2;
            break;
        case X25_FAC_ACK_TIMEOUT:
            if (length != 2)
                return -EINVAL;
            dce.ack_timeout = get_unaligned((unsigned short *)ptr);
            ptr += 2;
            len += 2;
            break;
        case X25_FAC_WINDOW_TIMEOUT:
            if (length != 2)
                return -EINVAL;
            dce.window_timeout = get_unaligned((unsigned short *)ptr);
            ptr += 2;
            len += 2;
            break;
        case X25_FAC_ETX_TIMEOUT:
            if (length != 2)
                return -EINVAL;
            dce.etx_timeout = get_unaligned((unsigned short *)ptr);
            ptr += 2;
            len += 2;
            break;
        default:
            ptr += length;
            len += length;
            break;
        }
    }

    if (len > skb->len)
        return -EINVAL;

    /* Negotiate throughput */
    if (dce.throughput < X25_MIN_THROUGHPUT)
        dce.throughput = X25_MIN_THROUGHPUT;
    else if (dce.throughput > X25_MAX_THROUGHPUT)
        dce.throughput = X25_MAX_THROUGHPUT;
    new->throughput = dce.throughput;

    /* Negotiate packet size */
    if (dce.packet_size < X25_MIN_PACKET_SIZE)
        dce.packet_size = X25_MIN_PACKET_SIZE;
    else if (dce.packet_size > X25_MAX_PACKET_SIZE)
        dce.packet_size = X25_MAX_PACKET_SIZE;
    new->packet_size = dce.packet_size;

    /* Negotiate window size */
    if (dce.window_size < X25_MIN_WINDOW_SIZE)
        dce.window_size = X25_MIN_WINDOW_SIZE;
    else if (dce.window_size > X25_MAX_WINDOW_SIZE)
        dce.window_size = X25_MAX_WINDOW_SIZE;
    new->window_size = dce.window_size;

    new->reverse_charging = dce.reverse_charging;
    new->forward_charging = dce.forward_charging;
    new->call_back = dce.call_back;
    new->priority = dce.priority;
    new->etr = dce.etr;
    new->etx = dce.etx;
    new->ack_timeout = dce.ack_timeout;
    new->window_timeout = dce.window_timeout;
    new->etx_timeout = dce.etx_timeout;

    dte->reverse_charging = dce.reverse_charging;

    return len;
}

int x25_negotiate_facilities(struct sk_buff *skb, struct sock *sk,
                             struct x25_facilities *new,
                             struct x25_dte_facilities *dte)
{
    struct x25_facilities facilities;
    unsigned char *data = skb->data;
    int len = skb->len;
    int i = 0;

    memset(&facilities, 0, sizeof(facilities));

    if (len < 4)
        return -EINVAL;

    facilities.throughput = data[i++];
    facilities.packet_size = data[i++];
    facilities.window_size = data[i++];
    facilities.reverse_charging = data[i++];

    if (facilities.reverse_charging) {
        /* Handle reverse charging request */
        dte->reverse_charging = 1;
        dte->currency_units = (data[i] << 8) | data[i+1];
        dte->transmitting_currency = (data[i+2] << 8) | data[i+3];
        dte->receiving_currency = (data[i+4] << 8) | data[i+5];
        i += 6;
    }

    /* Negotiate throughput */
    if (facilities.throughput > X25_MAX_THROUGHPUT)
        new->throughput = X25_MAX_THROUGHPUT;
    else
        new->throughput = facilities.throughput;

    /* Negotiate packet size */
    if (facilities.packet_size > X25_MAX_PACKET_SIZE)
        new->packet_size = X25_MAX_PACKET_SIZE;
    else
        new->packet_size = facilities.packet_size;

    /* Negotiate window size */
    if (facilities.window_size > X25_MAX_WINDOW_SIZE)
        new->window_size = X25_MAX_WINDOW_SIZE;
    else
        new->window_size = facilities.window_size;

    new->reverse_charging = facilities.reverse_charging;

    printk(KERN_DEBUG "X.25: Negotiated throughput %d, packet size %d, window size %d\n",
           new->throughput, new->packet_size, new->window_size);

    return i;
}

int x25_negotiate_facilities(struct sk_buff *skb, struct sock *sk,
                             struct x25_facilities *new,
                             struct x25_dte_facilities *dte)
{
    struct x25_facilities local;
    int len = 0;
    u8 *ptr = skb->data;
    int i;

    memset(new, 0, sizeof(*new));
    memset(dte, 0, sizeof(*dte));

    for (i = 0; i < X25_FACILITIES_SIZE; i++) {
        if (ptr[i] == 0)
            break;
        len++;
    }

    if (len % 2 != 0)
        return -EINVAL;

    for (i = 0; i < len; i += 2) {
        int type = ptr[i];
        int value = ptr[i + 1];

        switch (type) {
        case X25_FAC_THROUGHPUT:
            if (value < 1 || value > 16)
                return -EINVAL;
            new->throughput = min_t(int, sk->x25->throughput, value);
            break;
        case X25_FAC_PACKET_SIZE:
            if (value < 16 || value > 64)
                return -EINVAL;
            new->packet_size = min_t(int, sk->x25->packet_size, value);
            break;
        case X25_FAC_WINDOW_SIZE:
            if (value < 1 || value > 128)
                return -EINVAL;
            new->window_size = min_t(int, sk->x25->window_size, value);
            break;
        case X25_FAC_DTE:
            if (value & 0x80)
                dte->reverse_charge = 1;
            break;
        default:
            break;
        }
    }

    return len;
}

int x25_negotiate_facilities(struct sk_buff *skb, struct sock *sk,
                             struct x25_facilities *new,
                             struct x25_dte_facilities *dte)
{
    struct x25_facilities called, calling;
    int len = 0;
    u8 *ptr;

    X25_INIT_FACILITIES(called);
    X25_INIT_FACILITIES(calling);

    ptr = skb->data;
    len = x25_unpack_facilities(skb, ptr, &called, &calling);

    if (len < 0)
        return len;

    if (called.reverse_charging)
        dte->reverse_charging = 1;

    new->throughput = min(called.throughput, calling.throughput);
    new->window_size = min(called.window_size, calling.window_size);
    new->packet_size = min(called.packet_size, calling.packet_size);

    if (new->throughput != called.throughput)
        printk(KERN_DEBUG "X.25: throughput negotiated down to %d\n",
               new->throughput);

    if (new->window_size != called.window_size)
        printk(KERN_DEBUG "X.25: window size negotiated down to %d\n",
               new->window_size);

    if (new->packet_size != called.packet_size)
        printk(KERN_DEBUG "X.25: packet size negotiated down to %d\n",
               new->packet_size);

    return len;
}
